from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
from itertools import combinations
import time

W = 7  # weeks
G = 8  # groups  
S = 4  # size of each group
P = 32  # players = G * S

def var(w, p, g):
    return w * P * G + p * G + g + 1

clauses = []
top_var = [W * P * G + 1]

# Constraint 1: Each player is in exactly one group per week
for w in range(W):
    for p in range(P):
        lits = [var(w, p, g) for g in range(G)]
        clauses.append(lits)
        for g1, g2 in combinations(range(G), 2):
            clauses.append([-var(w, p, g1), -var(w, p, g2)])

# Constraint 2: Each group has exactly S players per week
for w in range(W):
    for g in range(G):
        lits = [var(w, p, g) for p in range(P)]
        enc = CardEnc.equals(lits, bound=S, top_id=top_var[0], encoding=EncType.seqcounter)
        clauses.extend(enc.clauses)
        top_var[0] = enc.nv + 1

# Constraint 3: No pair of players in same group more than once
for p1, p2 in combinations(range(P), 2):
    for w1, w2 in combinations(range(W), 2):
        for g in range(G):
            for g2 in range(G):
                clauses.append([-var(w1,p1,g), -var(w1,p2,g), -var(w2,p1,g2), -var(w2,p2,g2)])

# Symmetry breaking: fix week 0
for p in range(P):
    g = p // S
    clauses.append([var(0, p, g)])

solver = Glucose4()
for cl in clauses:
    solver.add_clause(cl)

t = time.time()
result = solver.solve()
print(f"Result: {result}, Time: {time.time()-t:.2f}s")

if result:
    model = solver.get_model()
    model_set = set(model)

    schedule = []
    for w in range(W):
        week = []
        for p in range(P):
            for g in range(G):
                if var(w, p, g) in model_set:
                    week.append(g)
                    break
        schedule.append(week)

    # Verify
    pairs_seen = {}
    valid = True
    for w in range(W):
        for g in range(G):
            members = [p for p in range(P) if schedule[w][p] == g]
            if len(members) != S:
                print(f"ERROR: Week {w} Group {g} has {len(members)} members!")
                valid = False
            for p1, p2 in combinations(members, 2):
                pair = (min(p1,p2), max(p1,p2))
                if pair in pairs_seen:
                    print(f"ERROR: Pair {pair} appears twice!")
                    valid = False
                else:
                    pairs_seen[pair] = (w, g)

    if valid:
        print("Schedule is VALID!")

    flat = []
    for w in range(W):
        for p in range(P):
            flat.append(schedule[w][p])

    print(f"Flat list length: {len(flat)}")
